<template>
    <div class="header-bar">
    <!-- 搜索框 -->
     <div class="search-box">
        <el-input
      v-model="input2"
      style="width: 240px"
      placeholder="Please Input"
      :suffix-icon="Search"
    />
     </div>   
     
    <!--用户信息 -->
    <div class="user-info">
    <!-- 通知 -->
     <div class="notification">
      <el-badge :value="99" class="notification-item">
        <el-icon><img class="menu-icon" src="@/assets/icon/notification.png" alt="" /></el-icon>
      </el-badge>
     </div>

      <!-- 用户下拉菜单 -->
      <el-dropdown trigger="click" @command="handleCommand">
        <div class="user-dropdown">
          <div class="avatar">
            <img
              v-if="user.avatar && !avatarError"
              :src="user.avatar"
              alt=""
              @error="avatarError = true"
            />
            <span v-else>{{ (user.nickname || 'A').charAt(0) }}</span>
          </div>
          <div class="user-detail">
            <div class="user-name">{{ user.nickname }}</div>
            <div class="user-role">{{ roleName(user.role) }}</div>
          </div>
        </div>
        <template #dropdown>
          <el-dropdown-menu>
            <el-dropdown-item command="logout">退出登录</el-dropdown-item>
          </el-dropdown-menu>
        </template>
      </el-dropdown>
    </div>
    </div>
</template>

<script setup>
import { ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessageBox, ElMessage } from 'element-plus'
import { Search } from '@element-plus/icons-vue'

const router = useRouter()
const input2 = ref('')

// 解析登录用户信息（coffer_user 存储的是 JSON 字符串）
const user = ref(JSON.parse(localStorage.getItem('coffer_user') || '{}'))
// 头像加载失败的标记（失败后显示昵称首字母）
const avatarError = ref(false)
watch(user, () => { avatarError.value = false }, { deep: true })

// 角色编码 -> 名称映射：1普通用户,2客服,3运营,4审核,9超级管理员
const roleMap = {
  1: '普通用户',
  2: '客服',
  3: '运营',
  4: '审核',
  9: '超级管理员'
}
const roleName = (role) => roleMap[role] || '暂无角色'

const handleCommand = (command) => {
  if (command === 'logout') {
    ElMessageBox.confirm('确定要退出登录吗？', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    }).then(() => {
      // localStorage.removeItem('coffer_token')
      localStorage.removeItem('coffer_user')
      ElMessage.success('已退出登录')
      router.push('/login')
    }).catch(() => {})
  }
}
</script>

